-- Borean Tundra: quest credit for Monitoring the Rift and Burn in Effigy, given by a spell hit on a bunny or NPC.
-- The creatures had no SmartAI here, so the quests could not be completed.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (25308,25309,25310,25510,25511,25512,25513) AND `ScriptName` = '';
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (25308,25309,25310,25510,25511,25512,25513);
